seq = open('region.fasta').read().split('\n',1)[1].replace('\n','').strip()
print(len(seq))
def rc(s):
    import re
    return s[::-1].translate(str.maketrans('ACGT','TGCA'))
# find ORFs
def orfs(s, minlen=100):
    res=[]
    for f in range(3):
        # to stop codons
        codons=[s[i:i+3] for i in range(f,len(s)-2,3)]
        prot=''.join('*' if c in ('TAA','TAG','TGA') else 'X' for c in codons)
        start=None
        for i,ch in enumerate(prot):
            if ch=='*':
                if start is not None:
                    if i-start>=minlen//3:
                        res.append((f, start*3+f, i*3+f, (i-start)))
                    start=None
            else:
                if start is None: start=i
        if start is not None and len(prot)-start>=minlen//3:
            res.append((f,start*3+f,len(s),len(prot)-start))
    return res
for name,s in [('fwd',seq),('rev',rc(seq))]:
    print(name)
    for r in sorted(orfs(s), key=lambda x:-x[3]):
        print('  frame',r[0],'start',r[1],'end',r[2],'aa',r[3], 'ATG' if s[r[1]:r[1]+3]=='ATG' else s[r[1]:r[1]+3])
