seq = open('region.fasta').read().split('\n',1)[1].replace('\n','').strip()
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
codon={}
i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            codon[b1+b2+b3]=aas[i]; i+=1
def rc(s): return s[::-1].translate(str.maketrans('ACGT','TGCA'))
def trans(s,f=0): return ''.join(codon[s[i:i+3]] for i in range(f,len(s)-2,3))

def listorfs(s,minaa=25):
    out=[]
    for f in range(3):
        p=trans(s,f)
        start=None
        for i,c in enumerate(p):
            if c=='*':
                if start is not None and i-start>=minaa:
                    out.append((f,start*3+f,(i)*3+f,i-start,s[start*3+f:start*3+f+3]))
                start=None
            else:
                if start is None: start=i
        if start is not None and len(p)-start>=minaa:
            out.append((f,start*3+f,len(p)*3+f,len(p)-start,s[start*3+f:start*3+f+3]))
    return sorted(out,key=lambda x:-x[3])

print("FORWARD strand ORFs >=25 aa:")
for o in listorfs(seq,25): print(f"  frame {o[0]} {o[1]}-{o[2]}  {o[3]} aa  first codon {o[4]}")
print()
print("REVERSE strand ORFs >=25 aa (coords in rev-complement space):")
for o in listorfs(rc(seq),25): print(f"  frame {o[0]} {o[1]}-{o[2]}  {o[3]} aa  first codon {o[4]}  -> fwd {3000-o[2]}-{3000-o[1]}")
